import{_ as o,a0 as l,w as d,s as r,ao as u,I as e,x as n,a1 as t,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"我的冒險旅程之遷移回 Windows | LCTT x X-CMD","titleTemplate":false,"description":"我的冒險旅程之遷移回 Windows | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我的冒險旅程之遷移回 Windows | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我的冒險旅程之遷移回 Windows | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171113 My Adventure Migrating Back To Windows","title":"我的冒險旅程之遷移回 Windows","tag":"201804","desc":""},"relativePath":"201804/20171113 My Adventure Migrating Back To Windows.md","filePath":"[post].md"}'),p={name:"201804/20171113 My Adventure Migrating Back To Windows.md"};function w(h,i,b,W,m,x){const a=l("Link");return d(),r("div",null,[i[13]||(i[13]=u('<h1 id="我的冒險旅程之遷移回-windows" tabindex="-1">我的冒險旅程之遷移回 Windows <a class="header-anchor" href="#我的冒險旅程之遷移回-windows" aria-label="Permalink to “我的冒險旅程之遷移回 Windows”">​</a></h1><p>我已經主要使用 Linux 大約 10 年了，而且主要是 Ubuntu。但在最新發布的版本中，我決定重新回到我通常不喜歡的操作系統： Windows 10。</p><p><img src="https://winaero.com/blog/wp-content/uploads/2016/07/Ubutntu-on-Windows-10-logo-banner.jpg" alt="Ubuntu On Windows"></p><p>我一直是 Linux 的粉絲，我最喜歡的兩個發行版是 Debian 和 Ubuntu。現今作為一個服務器操作系統，Linux 是完美無暇的，但在桌面上一直存在不同程度的問題。</p><p>最近一系列的問題讓我意識到，我不需要使用 Linux 作為我的桌面操作系統，我仍然是一個 Linux 粉絲，但基於我安裝 Ubuntu 17.10 的經驗，我已經決定回到 Windows。</p><h3 id="什麼使我選擇了迴歸" tabindex="-1">什麼使我選擇了迴歸 <a class="header-anchor" href="#什麼使我選擇了迴歸" aria-label="Permalink to “什麼使我選擇了迴歸”">​</a></h3><p>問題是，當 Ubuntu 17.10 出來後，我像往常一樣進行全新安裝，但遇到了一些非常奇怪的新問題。</p><ul><li>Dell D3100 Dock 不再工作（包括臨時規避方案也沒用）</li><li>Ubuntu 意外死機（隨機）</li><li>雙擊桌面上的圖標沒反應</li><li>使用 HUD 搜索諸如“tweaks”之類的程序會嘗試安裝 META 桌面版本</li><li>GUI 比標準的 GNOME 感覺更糟糕</li></ul><p>現在我確實考慮回到使用 Ubuntu 16.04 或另一個發行版，但是我覺得 Unity 7 是最精緻的桌面環境，而另外唯一一個優雅且穩定的是 Windows 10。</p><p>除此之外，使用 Linux 而不是使用 Windows 也有一些固有的問題，如：</p><ul><li>大多數商用軟件不可用，E.G Maya、 PhotoShop、 Microsoft Office（大多數情況下，替代品並不相同）等等。</li><li>大多數遊戲都沒有移植到 Linux 上，包括來自 EA、 Rockstar Ect. 等主要工作室的遊戲。</li><li>對於大多數硬件來説，其 Linux 驅動程序是廠商的次要考慮。</li></ul><p>在決定使用 Windows 之前，我確實考慮過其他發行版和操作系統。</p><p>與此同時，我看到了更多的“微軟愛 Linux ”的行動，並且瞭解了 WSL。他們的新開發者的關注角度對我來説很有意思，於是我試了一下。</p><h3 id="我在-windows-找到了什麼" tabindex="-1">我在 Windows 找到了什麼 <a class="header-anchor" href="#我在-windows-找到了什麼" aria-label="Permalink to “我在 Windows 找到了什麼”">​</a></h3><p>我使用計算機主要是為了編程，我也使用虛擬機、git 和 ssh，並且大部分工作依賴於 bash。我偶爾也會玩遊戲，觀看 netflix 和一些輕鬆的辦公室工作。</p><p>總之，我期待在 Ubuntu 中保留當前的工作流程並將其移植到 Windows 上。我也想利用 Windows 的優點。</p><ul><li>所有的 PC 遊戲支持 Windows</li><li>大多數程序是原生的</li><li>微軟辦公軟件</li></ul><p>雖然使用 Windows 有很多坑，但是我打算正確對待它，所以我不擔心一般的 Windows 故障，例如病毒和惡意軟件。</p><h3 id="windows-的子系統-linux-windows-上的-ubuntu-中的-bash" tabindex="-1">Windows 的子系統 Linux（Windows 上的 Ubuntu 中的 Bash） <a class="header-anchor" href="#windows-的子系統-linux-windows-上的-ubuntu-中的-bash" aria-label="Permalink to “Windows 的子系統 Linux（Windows 上的 Ubuntu 中的 Bash）”">​</a></h3><p>微軟與 Canonical 的密切合作將 Ubuntu 帶到了 Windows 上。在經過快速設置和啓動程序之後，你將擁有非常熟悉的 bash 界面。</p><p>我一直在研究其侷限性，但是在寫這篇文章時我碰到的唯一真正的限制是它從硬件中抽象了出來。例如，<code>lsblk</code> 不會顯示你有什麼分區，因為子系統裏的 Ubuntu 沒有提供這些信息。</p><p>但是除了訪問底層工具之外，我發現其體驗非常熟悉，也很棒。</p><p>我在下面的工作流程中使用了它。</p><ul><li>生成 SSH 密鑰對</li><li>使用 Git 和 Github 來管理我的倉庫</li><li>SSH 到幾個服務器，包括不用密碼</li><li>為本地資料庫運行 MySQL</li><li>監視系統資源</li><li>使用 Vim 編輯配置文件</li><li>運行 Bash 腳本</li><li>運行本地 Web 服務器</li><li>運行 PHP、NodeJS</li></ul><p>到目前為止，它已經被證明是非常強大的工具。除了是在 Windows 10 用户界面之中，我的工作流程感覺和我在 Ubuntu 上幾乎一樣。儘管我的多數工作可以在 WSL 中處理，但我仍然打算通過虛擬機進行更深入的工作，這可能超出了 WSL 的範圍。</p><h3 id="不需要用-wine" tabindex="-1">不需要用 Wine <a class="header-anchor" href="#不需要用-wine" aria-label="Permalink to “不需要用 Wine”">​</a></h3><p>我遇到的另一個主要問題是兼容性問題。我很少使用 Wine 來使用 Windows 軟件。（LCTT 譯註：Wine 是可以使 Linux 上運行 Windows 應用的軟件）但是有時它是必需的，儘管通常體驗不是很好。</p><h4 id="heidisql" tabindex="-1">HeidiSQL <a class="header-anchor" href="#heidisql" aria-label="Permalink to “HeidiSQL”">​</a></h4><p>我首先安裝的程序之一是 HeidiSQL，它是我最喜歡的資料庫客户端之一。它可以在 Wine 下工作，但是感覺很不好，所以我在 Linux 下丟掉它而使用了 MySQL Workbench。回到了 Windows 中，就像一個可靠的老朋友回來了。</p><h4 id="遊戲平台-steam" tabindex="-1">遊戲平台 / Steam <a class="header-anchor" href="#遊戲平台-steam" aria-label="Permalink to “遊戲平台 / Steam”">​</a></h4><p>沒有遊戲的 Windows 電腦是無法想像的。我從 Steam 的網站上安裝了它，我的 Linux 遊戲，加上我的 Windows 遊戲就變大了 5 倍，並且包括 GTA V （LCTT 譯註： GTA V 是一款名叫俠盜飛車的遊戲) 等 AAA 級遊戲。而這些我在 Ubuntu 中只能夢想。</p><p>我對 SteamOS 有很大的期望，並且一直會持續如此。但是我認為在可預見的將來，它不會在任何地方的遊戲市場中嶄露頭角。所以如果你想在 PC 上玩遊戲，你確實需要 Windows。</p><p>還有一點需要注意的是， 你的 nvidia 顯卡的驅動程序會得到很好的支持，這使得像 TF2 （LCTT 譯註： 這是一款名叫軍團要塞 2 的遊戲）這樣的一些 Linux 原生遊戲運行的稍好一些。</p><p><strong>Windows 在遊戲方面總是優越的，所以這並不令人感到意外。</strong></p><h3 id="從-usb-硬盤運行-為什麼" tabindex="-1">從 USB 硬盤運行，為什麼 <a class="header-anchor" href="#從-usb-硬盤運行-為什麼" aria-label="Permalink to “從 USB 硬盤運行，為什麼”">​</a></h3><p>我在我的主固態硬盤上運行 Linux，但在過去，我是從 usb 棒和 usb 硬盤運行它的。我習慣了 Linux 的這種持久性，這讓我可以在不丟失主要操作系統的情況下長期嘗試多個版本。現在我嘗試將 Windows 安裝到 USB 連接的硬盤上時，它無法工作也不可能工作。所以當我將 Windows 硬盤分區的克隆作為備份時，我很驚訝我可以通過 USB 啓動它。</p><p>這對我來説已經成為一個方便的選擇，因為我打算將我的工作筆記本電腦遷移回 Windows，但如果不想冒險，那就把它扔在那裏吧。</p><p>所以我在過去的幾天裏，我使用 USB 來運行它，除了一些錯誤的消息外，我沒有通過 USB 運行發現它真正的缺點。</p><p>這樣做主要的問題是：</p><ul><li>較慢的啓動速度</li><li>惱人的信息：不要拔掉你的 USB</li><li>無法激活它</li></ul><p><strong>我可能會寫一篇關於 USB 驅動器上的 Windows 的文章，這樣我們可以有更詳細的瞭解。</strong></p><h3 id="那麼結論是什麼" tabindex="-1">那麼結論是什麼？ <a class="header-anchor" href="#那麼結論是什麼" aria-label="Permalink to “那麼結論是什麼？”">​</a></h3><p>我使用 Windows 10 大約兩週了，並沒有注意到它對我的工作流程有任何的負面影響。儘管過程會有一些小問題，但我需要的所以工具都在手邊，並且操作系統一般都在運行。</p><h3 id="我會留在-windows嗎" tabindex="-1">我會留在 Windows嗎？ <a class="header-anchor" href="#我會留在-windows嗎" aria-label="Permalink to “我會留在 Windows嗎？”">​</a></h3><p>雖然現在還為時尚早，但我想在可見的未來我會堅持使用 Windows。</p><hr>',46)),e("p",null,[i[1]||(i[1]=n("via: ",-1)),t(a,{href:"https://www.chris-shaw.com/blog/my-adventure-migrating-back-to-windows"},{default:s(()=>[...i[0]||(i[0]=[n("https://www.chris-shaw.com/blog/my-adventure-migrating-back-to-windows",-1)])]),_:1})]),e("p",null,[i[5]||(i[5]=n("作者：",-1)),t(a,{href:"https://www.chris-shaw.com"},{default:s(()=>[...i[2]||(i[2]=[n("Christopher Shaw",-1)])]),_:1}),i[6]||(i[6]=n(" 譯者：",-1)),t(a,{href:"https://github.com/MjSeven"},{default:s(()=>[...i[3]||(i[3]=[n("MjSeven",-1)])]),_:1}),i[7]||(i[7]=n(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:s(()=>[...i[4]||(i[4]=[n("wxy",-1)])]),_:1})]),e("p",null,[i[10]||(i[10]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[8]||(i[8]=[n("LCTT",-1)])]),_:1}),i[11]||(i[11]=n(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:s(()=>[...i[9]||(i[9]=[n("Linux中國",-1)])]),_:1}),i[12]||(i[12]=n(" 榮譽推出",-1))])])}const S=o(p,[["render",w]]);export{f as __pageData,S as default};
